#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

int main(void)
{
    RCC->AHB1ENR |= (0b1 << 0); /* Enable GPIOA clock, encender señal de reloj*/

    GPIOA->MODER &= ~(0b11 <<  5*2); 
    GPIOA->MODER |= (0b01 <<  5*2); /*set PA5 as output*/

    GPIOA->OTYPER &= ~(0b1 << 5);

    GPIOA->OSPEEDR |= (0b11 << 5*2);

    GPIOA->PUPDR &= ~(0b11 << 5*2); /*no pull-up, no pull-down*/

    GPIOA->ODR |= (0b1 << 5); /*set PA5 high*/


    /* Loop forever */
	for(;;);
}

